theorem TxBody.mem_creates (body : TxBody) {i : Nat}
    (hi : i < body.outputs.val.length) :
    (⟨body.txid, UInt32.ofNat i⟩, body.outputs.val[i]) ∈ body.creates

theorem UtxoSet.lookup_apply_output {utxos : UtxoSet} {provenance : Provenance}
    {body : TxBody} (houtputs : body.outputs.val.length ≤ 2 ^ 32) {i : Nat}
    (hi : i < body.outputs.val.length) :
    (utxos.apply provenance body).lookup ⟨body.txid, UInt32.ofNat i⟩
      = some ⟨body.outputs.val[i], provenance⟩

theorem witnessCommitment_binding {r₁ r₂ : Hash256} {v₁ v₂ : Bytes 32}
    (h : witnessCommitment r₁ v₁ = witnessCommitment r₂ v₂) :
    (r₁ = r₂ ∧ v₁ = v₂) ∨ Sha256.Collision

theorem root_binding_of_length_eq {xs ys : List Hash256}
    (hlen : xs.length = ys.length) (hroot : root xs = root ys) :
    xs = ys ∨ Sha256.Collision
